const body = $input.first().json.body || {};
const brief = body.product_brief || {};
const hook = body.hook || {};
const productName = brief.product_name || '这款产品';
const title = hook.title || productName + '真的值得买吗？';
const points = Array.isArray(brief.core_selling_points) ? brief.core_selling_points : [];
const point1 = points[0] || '解决真实使用痛点';
const point2 = points[1] || '体验自然、上手简单';
const language = body.language || '中文';
const contentType = body.content_type || '固定达人口播';
const script = [
  '【0-3s 开场】' + title,
  '【3-7s 痛点】以前我最在意的是：' + (brief.pain_points || '买之前信息太多，却很难判断是否适合自己。'),
  '【7-12s 产品】实际体验后，' + productName + '最打动我的是' + point1 + '，而且' + point2 + '。',
  '【12-15s 行动】如果你也在找更省心的选择，可以点开详情看看。'
].join('\n\n');
return [{ json: {
  ok: true,
  script_record_id: 'script_' + Date.now(),
  product_record_id: body.product_record_id || '',
  script_text: script,
  script,
  cta: '点开详情，确认它是否适合你。',
  script_cta: '点开详情，确认它是否适合你。',
  visual_logic: '0-3 秒人物近景提出 Hook；3-7 秒展示痛点场景；7-12 秒产品特写与使用动作；12-15 秒人物回到镜头并给出 CTA。',
  script_visual: '0-3 秒人物近景提出 Hook；3-7 秒展示痛点场景；7-12 秒产品特写与使用动作；12-15 秒人物回到镜头并给出 CTA。',
  duration_seconds: 15,
  language,
  content_type: contentType
} }];
